		'name' { 'string' }
		'parent_id' { '?int' }
		else { '' }
	}
}

// order_by_parent_name orders the rows by the `name` of their `parent`.
pub fn (q CategoryQuery) order_by_parent_name() CategoryQuery {
	return q.order_by(load.Order{
		expr: '(SELECT "t1"."name" FROM "categories" AS "t1" WHERE "t1"."id" = "t0"."parent_id")'
	})
}

// order_by_parent_name_desc orders the rows by the `name` of their
// `parent`, descending.
