// with_named_children loads `children` as `configure` says into
// `named_children[name]`, besides any other load of it.
pub fn (q CategoryQuery) with_named_children(name string, configure ...fn (CategoryQuery) CategoryQuery) CategoryQuery {
	mut next := q
	mut named := q.named_children.clone()
	named[name] = configure
	next.named_children = named
	return next
}

// with_parent loads each row's `parent` (many_to_one `categories`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q CategoryQuery) with_parent(configure ...fn (CategoryQuery) CategoryQuery) CategoryQuery {
	mut next := q
	next.with_parent = true
	next.parent_fns = configure
	return next
}

// with_children loads each row's `children` (one_to_many `categories`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q CategoryQuery) with_children(configure ...fn (CategoryQuery) CategoryQuery) CategoryQuery {
	mut next := q
	next.with_children = true
	next.children_fns = configure
	return next
}

// all returns the matching rows, with the requested edges.
pub fn (q CategoryQuery) all() ![]CategoryNode {
	rows := load.select_where[models.Category](q.graph.client.conn, q.graph.client.prepare_query('categories', q.query)!)!
	return q.nodes(rows)
}

// first returns the first matching row, with the requested edges, or a
// `NotFoundError`.
pub fn (q CategoryQuery) first() !CategoryNode {
	nodes := q.limit(1).all()!
	if nodes.len == 0 {
		return NotFoundError{
			table: 'categories'
		}
	}
	return nodes[0]
}

// nodes loads the requested edges onto `rows`, which the caller already has: one
// query per edge, however many rows there are.
pub fn (q CategoryQuery) nodes(rows []models.Category) ![]CategoryNode {
	mut nodes := rows.map(CategoryNode{
		graph:    q.graph
		category: it
	})
	if q.with_parent {
		found := q.load_parent(rows, q.parent_fns)!
		for mut node in nodes {
			// at most one each: the first, in the order of the query
			list := found[node.category.id.str()] or { [] }
			if list.len > 0 {
				node.parent = &CategoryNode{
					...list[0]
				}
			}
			node.loaded << 'parent'
		}
	}
	if q.with_children {
		found := q.load_children(rows, q.children_fns)!
		for mut node in nodes {
			node.children = found[node.category.id.str()] or { [] }
			node.loaded << 'children'
		}
	}
	for name, fns in q.named_children {
		found := q.load_children(rows, fns)!
		for mut node in nodes {
			node.named_children[name] = found[node.category.id.str()] or { [] }
		}
	}
	return nodes
}

// load_parent loads the `parent` of `rows`, keyed by each row's key.
fn (q CategoryQuery) load_parent(rows []models.Category, fns []fn (CategoryQuery) CategoryQuery) !map[string][]CategoryNode {
	mut sub := q.graph.categories()
	for configure in fns {
		sub = configure(sub)
	}
	mut keys := []string{}
	for row in rows {
		if fk := row.parent_id {
			keys << fk.str()
		}
	}
	targets := sub.nodes(load.select_in[models.Category](q.graph.client.conn, 'id',
		load.unique(keys),
		query: q.graph.client.prepare_edge_query('categories', sub.query)!
	)!)!
	mut by_key := map[string]CategoryNode{}
	for target in targets {
		by_key[target.category.id.str()] = target
	}
	mut found := map[string][]CategoryNode{}
	for row in rows {
		fk := row.parent_id or { continue }
		if target := by_key[fk.str()] {
			found[row.id.str()] = [target]
		}
	}
	return found
}

// parent_or_err returns the `parent`: a `NotLoadedError` when the query didn't
// load it, a `NotFoundError` when the row has none.
pub fn (n CategoryNode) parent_or_err() !&CategoryNode {
	if 'parent' !in n.loaded {
		return NotLoadedError{
			edge: 'categories.parent'
		}
	}
	if target := n.parent {
		return target
	}
	return NotFoundError{
		table: 'categories'
	}
}

// load_children loads the `children` of `rows`, keyed by each row's key.
fn (q CategoryQuery) load_children(rows []models.Category, fns []fn (CategoryQuery) CategoryQuery) !map[string][]CategoryNode {
	mut sub := q.graph.categories()
	for configure in fns {
		sub = configure(sub)
	}
	children := sub.nodes(load.select_each[models.Category](q.graph.client.conn, 'parent_id',
		rows.map(it.id.str()),
		query: q.graph.client.prepare_edge_query('categories', sub.query)!
	)!)!
	mut by_parent := map[string][]CategoryNode{}
	for child in children {
		if parent := child.category.parent_id {
			by_parent[parent.str()] << child
		}
	}
	return by_parent
}

// children_or_err returns the `children`, or a `NotLoadedError` when the query
// didn't load them.
pub fn (n CategoryNode) children_or_err() ![]CategoryNode {
	if 'children' !in n.loaded {
		return NotLoadedError{
			edge: 'categories.children'
		}
	}
	return n.children
}

// query_parent starts a query of this row's `parent`, which matches
// nothing when the row has none.
pub fn (n CategoryNode) query_parent() CategoryQuery {
	key := n.category.parent_id or { return n.graph.categories().where(load.in_ints('id', [])) }
	return n.graph.categories().where(load.eq('id', key))
}

// query_children starts a query of this row's `children`.
pub fn (n CategoryNode) query_children() CategoryQuery {
	return n.graph.categories().where(load.eq('parent_id', n.category.id))
}
